import { useReducer } from 'react';

const produk = [
  { id: 1, nama: 'Kopi Susu', harga: 15000 },
  { id: 2, nama: 'Teh Melati', harga: 8000 },
];

function reducer(isi, aksi) {
  switch (aksi.type) {
    case 'tambah': {
      const ada = isi.find((b) => b.id === aksi.produk.id);
      if (ada) return isi.map((b) => (b.id === ada.id ? { ...b, jumlah: b.jumlah + 1 } : b));
      return [...isi, { ...aksi.produk, jumlah: 1 }];
    }
    case 'kurang':
      return isi
        .map((b) => (b.id === aksi.id ? { ...b, jumlah: b.jumlah - 1 } : b))
        .filter((b) => b.jumlah > 0);
    case 'kosongkan':
      return [];
    default:
      throw new Error('Aksi tidak dikenal: ' + aksi.type);
  }
}

export default function App() {
  const [keranjang, dispatch] = useReducer(reducer, []);
  const total = keranjang.reduce((t, b) => t + b.harga * b.jumlah, 0);

  return (
    <div>
      {produk.map((p) => (
        <button key={p.id} onClick={() => dispatch({ type: 'tambah', produk: p })}>+ {p.nama}</button>
      ))}
      <ul>
        {keranjang.map((b) => (
          <li key={b.id}>
            {b.nama} x{b.jumlah}{' '}
            <button onClick={() => dispatch({ type: 'kurang', id: b.id })}>−</button>
          </li>
        ))}
      </ul>
      <p>Total: Rp{total.toLocaleString('id-ID')}</p>
      <button onClick={() => dispatch({ type: 'kosongkan' })}>Kosongkan</button>
    </div>
  );
}
